// firmware/src/ui/fonts.h -- anti-aliased Nunito fonts (ASCII + Latin-1)
//
// All UI text goes through these smooth fonts (generated by
// tools/make_fonts.py into font_data.h). Text is UTF-8; accents, ñ, ¿ ¡ ° ·
// are included. FONT_CLOCK only has the digits, ':' and '-'.
#pragma once
#include <stdint.h>

enum class UiFont : uint8_t { SMALL, BODY, TITLE, CLOCK };

// Makes f the current font of the main tft (loads only when it changes) and
// returns its line height in px. Smooth text is drawn with tft.drawString(s,
// x, y) after setTextColor(fg, bg): glyph edges are blended into bg.
int useFont(UiFont f);
// Unloads the smooth font so TFT_eSPI's built-in bitmap fonts (font 1, the
// tiny 5x7 one) can be used; the next useFont() reloads.
void useBuiltinFont();
// Line height of f (without changing the current font).
int fontLineH(UiFont f);
